import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

class AppLocalizations {
  const AppLocalizations(this.locale);

  final Locale locale;

  static const supportedLocales = [Locale('en'), Locale('ar'), Locale('de')];

  static AppLocalizations of(BuildContext context) {
    return Localizations.of<AppLocalizations>(context, AppLocalizations) ??
        const AppLocalizations(Locale('en'));
  }

  String text(String key) {
    final value = _translations[locale.languageCode]?[key];
    if (value != null) return value;
    assert(() {
      debugPrint(
        'Missing TaskMaster Pro translation: ${locale.languageCode}.$key',
      );
      return true;
    }());
    if (kDebugMode) return '⟦$key⟧';
    return switch (locale.languageCode) {
      'ar' => 'النص غير متاح',
      'de' => 'Text nicht verfügbar',
      _ => 'Text unavailable',
    };
  }

  String format(String key, Map<String, Object?> values) {
    var result = text(key);
    for (final entry in values.entries) {
      result = result.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return result;
  }

  String count(String singularKey, String pluralKey, int value) {
    final key = locale.languageCode == 'ar'
        ? switch (value) {
            0 => '${pluralKey}_zero',
            1 => singularKey,
            2 => '${pluralKey}_two',
            _ => pluralKey,
          }
        : value == 1
        ? singularKey
        : pluralKey;
    return format(key, {'count': value});
  }

  String taskStatus(String status, {bool compact = false}) {
    final key = switch (status) {
      'ready' => compact ? 'status_ready_compact' : 'status_ready',
      'in_progress' || 'running' => 'status_running',
      'paused' => 'status_paused',
      'completed' => 'status_completed',
      'overdue' => 'status_overdue',
      'waiting_review' => 'status_waiting_review',
      'interrupted' => 'status_interrupted',
      'scheduled' => 'status_scheduled',
      'cancelled' => 'status_cancelled',
      _ => 'status_ready',
    };
    return text(key);
  }

  String executionMode(String mode) {
    return text(switch (mode) {
      'pomodoro' => 'mode_pomodoro',
      'continuous' => 'mode_continuous',
      'checklist' => 'mode_checklist',
      'reading' => 'mode_reading',
      'habit' => 'mode_habit',
      'event' => 'mode_event',
      'hybrid' => 'mode_hybrid',
      _ => 'mode_manual',
    });
  }

  String duration(Duration value) {
    final hours = value.inHours;
    final minutes = value.inMinutes.remainder(60);
    final seconds = value.inSeconds.remainder(60);
    final parts = <String>[];
    if (hours > 0) {
      parts.add(
        hours == 1
            ? text('duration_hour')
            : format('duration_hours', {'count': hours}),
      );
    }
    if (minutes > 0) {
      parts.add(format('duration_minutes', {'count': minutes}));
    }
    if (parts.isEmpty || (hours == 0 && minutes == 0)) {
      parts.add(format('duration_seconds', {'count': seconds}));
    }
    return parts.join(locale.languageCode == 'ar' ? ' و' : ' ');
  }

  static bool get translationsComplete {
    final english = _translations['en']!.keys.toSet();
    return _translations.entries.every(
      (entry) =>
          entry.value.keys.toSet().containsAll(english) &&
          english.containsAll(entry.value.keys),
    );
  }

